export type UuidRNG = () => Uint8Array;

/**
 * @typedef {Object} UuidRNGOptions
 * @prop {UuidRNG} [rng] A function that returns a list of randomly generated bytes
 * @prop {Uint8Array} [random] A list of randomly generated bytes
 */

export interface UuidRNGOptions {
	/**
	 * A function that returns a list of randomly generated bytes.
	 */
	rng?: UuidRNG;
	/**
	 * A list of randomly generated bytes.
	 */
	random?: Uint8Array;
}

export interface UuidRNGConfig {
	rng: UuidRNG | undefined;
	random: Uint8Array | undefined;
}
